"""Narration for the UPSC Animated monsoon video with the free Kokoro voice (bf_emma), one segment per scene.
   /tmp/claude-0/kvenv/bin/python scripts/monsoon_narrate.py   (model files in /tmp/claude-0/kokoro)
Writes public/monsoon/narration.wav and src/monsoon/narration.json (segment id, text, caption text, start, end)."""
import json, os, numpy as np, soundfile as sf
from kokoro_onnx import Kokoro
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
K = "/tmp/claude-0/kokoro"
# (id, spoken text, caption text if different, pause before in seconds)
import re
RAW = [
 ("hook", "Every year, one wind decides the price of your food, the interest on your loan, and the income of nearly half of India's workers. It arrives on a date you can almost set your calendar by. In {twenty twenty-five|2025}, it reached Kerala on the {twenty-fourth|24th} of May, the earliest since {two thousand and nine|2009}. This is the Indian monsoon. Stay till the end, and you will be able to draw the whole system from memory.", 0.6),
 ("intro", "What is the monsoon? The word comes from the Arabic mausim, meaning season of winds. It is a seasonal reversal of wind direction, driven by the temperature difference between the heated Indian landmass and the cooler oceans around it. It brings about {seventy-five|75} percent of India's annual rainfall. A strong monsoon means bumper crops and full reservoirs. A weak one can mean drought.", 0.6),
 ("phases", "The monsoon has two phases. Phase one is the southwest monsoon, the wet phase, from June to September. Winds blow from sea to land, and deliver about three quarters of the year's rain, most of all on the Western Ghats and the northeast. Phase two is the northeast, or retreating, monsoon, from October to December. Now the winds blow from land to sea. They are mostly dry, but they give Tamil Nadu about {forty-eight|48} percent of its annual rain, according to the {I M D|IMD}, and they also water coastal Andhra.", 0.6),
 ("drivers", "Why does it happen? Think of a giant sea breeze. First, differential heating. In summer, intense heat creates low pressure over the Thar Desert and the northern plains, while the cooler Indian Ocean holds high pressure. Air rushes from high to low, carrying moisture. Second, the {I T C Z|ITCZ}, a belt of low pressure near the Equator, shifts north over the Ganga plain and pulls the winds in. Third, the Himalayas. They act as a high wall, stop the moist winds from escaping into Central Asia, and force them to rise and drop their rain over India.", 0.6),
 ("branches", "When the monsoon hits the southern tip of India, it splits in two. The Arabian Sea branch slams into the Western Ghats and soaks the west coast. The Bay of Bengal branch moves up into the northeast, then turns west along the Ganga plain. The two branches finally meet over northwest India.", 0.6),
 ("shifts", "Is the monsoon changing? Yes. Scientists at the Indian Institute of Tropical Meteorology in Pune found a threefold rise in widespread extreme rain events over central India between {nineteen fifty|1950} and {twenty fifteen|2015}. Monsoon depressions are weakening, more rain is shifting toward the peninsula, and regions like Marathwada and Vidarbha face repeated droughts. And El Nino, a warming of the Pacific, weakens the monsoon winds. In the El Nino year of {twenty twenty-three|2023}, India received only {ninety-four|94} percent of its normal rain.", 0.6),
 ("onset", "How does the {I M D|IMD} declare that the monsoon has arrived? Not by the first shower. After the {tenth|10th} of May, three tests must be passed together. One, rainfall. At least {sixty|60} percent of {fourteen|14} stations across Kerala, Lakshadweep and coastal Karnataka must record {two point five millimetres|2.5 mm} or more, for two days in a row. Two, wind. Westerly winds must be deep, up to {six hundred hectopascals|600 hPa}, and blow at {fifteen to twenty|15 to 20} knots near the surface. Three, cloud. Outgoing longwave radiation, measured by satellites such as ISRO's INSAT three D, must fall below {two hundred watts per square metre|200 W/m²}. Low radiation means thick, tall rain clouds.", 0.6),
 ("agri", "How does the monsoon run Indian farming? There are two crop seasons. Kharif crops are sown in June and July, when the rains arrive, and harvested in September and October. They need a lot of water: rice, maize, cotton, soybean, sugarcane and groundnut. Rabi crops are sown in October and November, as the monsoon retreats, and harvested in March and April. They use moisture left in the soil, and winter rain from western disturbances: wheat, barley, mustard, gram and peas. But rabi depends on the monsoon too. Monsoon rain fills the reservoirs and recharges the groundwater that irrigate the winter crop. And a dry spell in July can wipe out kharif seedlings.", 0.6),
 ("wettest", "Where does it rain the most? In Meghalaya, the Khasi Hills form a funnel. Winds from the Bay of Bengal cross the plains of Bangladesh, hit the hills, and are forced to rise. This is orographic lift. So Mawsynram averages about {eleven thousand eight hundred and seventy millimetres|11,870 mm} of rain a year, among the highest on Earth, with Cherrapunji close behind. On the Western Ghats, Amboli gets around {seven thousand five hundred|7,500}, Agumbe, the Cherrapunji of the south, about {seven thousand two hundred|7,200}, and Mahabaleshwar, source of the Krishna river, about {five thousand six hundred|5,600}.", 0.6),
 ("timetable", "When does it reach you? These are the {I M D's|IMD's} normal dates. Around the {twenty-second|22nd} of May, the Andaman and Nicobar Islands. On the first of June, Kerala. By about the {eleventh|11th} of June, Mumbai and Kolkata. By the {twentieth|20th}, central India. Near the end of June, Delhi. And by the {eighth|8th} of July, the whole country is covered. Then the journey reverses. Withdrawal begins from west Rajasthan around the {seventeenth|17th} of September, and is complete by about the {fifteenth|15th} of October. Crossing the Bay of Bengal, the winds pick up moisture and become the northeast monsoon.", 0.6),
 ("harvest", "Most of the year's water arrives in just four months. So how do we store it? Traditionally, Rajasthan built taankas, underground tanks that collect rooftop rain. Villages built johads and check dams, small earthen walls that hold runoff and recharge the groundwater. In the northeast, bamboo pipes carry spring water drop by drop to the crops. Modern cities add rooftop rainwater harvesting, where pipes lead rain from the roof through a filter into a recharge well. And permeable pavements and restored lakes turn the city into a sponge.", 0.6),
 ("economy", "Why does a weak monsoon hurt everyone? Follow the chain. Rainfall below {ninety|90} percent of the long period average is a deficient monsoon. Kharif sowing falls. Food prices rise, especially pulses, rice and vegetables. Food is the largest part of India's consumer price index, so the Reserve Bank keeps interest rates high. About {forty-six|46} percent of India's workers depend on farming, so rural incomes fall. And sales of tractors, two-wheelers and consumer goods slow down. Farmers also pump more groundwater, which pushes up power demand.", 0.6),
 ("climate", "How is climate change rewriting the monsoon? The season's total still stays close to the long period average of {eighty-seven centimetres|87 cm}. But the pattern inside it is changing. Warmer air holds more moisture, about seven percent more for every degree Celsius. So we get long dry spells, broken by short, extreme bursts. And the rain is shifting. {I M D|IMD} data show falling rainfall over Uttar Pradesh, Bihar and West Bengal, while parts of western India and the southern peninsula see heavier floods.", 0.6),
 ("markets", "How do markets react? In mid April, the {I M D|IMD} issues its first long range forecast. If it predicts above normal rain, farm commodity prices ease, and shares of tractor, two-wheeler, fertiliser and consumer goods companies tend to rise. If it predicts below normal rain, futures prices of pulses, soybean, mustard and guar seed tend to jump on the commodity exchange, and rural demand stocks tend to fall. This is how markets work, not investment advice.", 0.6),
 ("tn", "Finally, a success story. In {two thousand and three|2003}, Tamil Nadu became the first Indian state to make rainwater harvesting compulsory for every building. The rule was strict: no harvesting system, no water connection. Roof water passes through a filter of sand, gravel and charcoal, and then into a recharge well. Within a few years, studies in Chennai reported the water table rising by several metres, and seawater intrusion being pushed back. Systems must be cleaned before each northeast monsoon.", 0.6),
 ("outro", "So here is the whole map in your mind. What: a seasonal reversal of winds, in two phases. Why: heating, the {I T C Z|ITCZ}, and the Himalayas. How it arrives: two branches, on a timetable, declared by three tests. Why it matters: crops, prices, and markets. And how we respond: store the rain, and prepare for a more extreme monsoon. If this helped, subscribe to UPSC Animated.", 0.8),
]
_sp = lambda t: re.sub(r"\{([^|}]*)\|([^}]*)\}", r"\1", t)
_cp = lambda t: re.sub(r"\{([^|}]*)\|([^}]*)\}", r"\2", t)
SEG = [(i, _sp(t), _cp(t), p) for i, t, p in RAW]
VOICE, SPEED = os.environ.get("VOICE", "bf_emma"), float(os.environ.get("SPEED", "0.84"))
EXTRA_PAUSE = float(os.environ.get("EXTRA_PAUSE", "0.7"))   # added breathing room between scenes
k = Kokoro(f"{K}/model.onnx", f"{K}/voices.npz")
sr, parts, meta, t = 24000, [], [], 0.0
for sid, text, cap, pause in SEG:
    pause += EXTRA_PAUSE
    parts.append(np.zeros(int(pause * sr), np.float32)); t += pause
    a, sr = k.create(text, voice=VOICE, speed=SPEED, lang="en-gb", sentence_pause=0.55, clause_pause=0.18)
    parts.append(a.astype(np.float32))
    meta.append({"id": sid, "speak": text, "text": cap or text, "start": round(t, 3), "end": round(t + len(a) / sr, 3)})
    t += len(a) / sr
    print(f"{sid:9s} {meta[-1]['start']:7.2f} {meta[-1]['end']:7.2f}")
parts.append(np.zeros(int(1.8 * sr), np.float32)); t += 1.8
audio = np.concatenate(parts); audio = audio / np.abs(audio).max() * 0.9
sf.write(os.path.join(ROOT, "public/wb/narration.wav"), audio, sr)
json.dump({"total": round(t, 3), "voice": VOICE, "segments": meta}, open(os.path.join(ROOT, "src/wb/narration.json"), "w"), indent=1)
print("total", round(t, 2))
